#!/bin/sh
# web2: server in tenant prod, VLAN 10, cabled to leaf2. Generated by fabctl render.
# Its gateway 10.10.10.1 is the anycast gateway: the same address and MAC on every leaf.
set -e
ip link set eth1 mtu 1500 up
ip addr replace 10.10.10.12/24 dev eth1
ip route replace default via 10.10.10.1
